from h import *
O=[]
O.append(R(6435021,
ar=("صلصة سالسا الفاصوليا السوداء الطازجة","هذه السالسا أفضل من أي شيء ستشتريه في برطمان! إنها لذيذة وسريعة وتستخدم مكونات طازجة قد تكون موجودة لديك في مطبخك بالفعل. وإن كنت لا ترغب في تقديمها مع الشيبس، فجرّبها مع الخيار أو الكرفس أو اليكاما. كما أنها تصلح كطبقة علوية رائعة للتاكو!","8","10 قطع شيبس + ¼ كوب سالسا",
["حوالي 80 قطعة شيبس التورتيلا (متعدد الحبوب، على شكل مغرفة)","1 كوب فاصوليا سوداء معلبة (مشطوفة ومصفاة)","2 حبة طماطم كبيرة (مقطّعة مكعبات)","¼ كوب بصل (مقطّع مكعبات صغيرة جدًا)","1 فص ثوم (مفروم)","2 ملعقة كبيرة عصير ليمون أخضر طازج","¼ كوب كزبرة خضراء طازجة (مفرومة)"],
["في وعاء متوسط، اخلط جميع المكونات ما عدا الشيبس.","قدّم السالسا في وعاء مع الشيبس على الجانب."],[],[])))
O.append(R(6435172,
es=("Sancocho de carne de res","Mis abuelos preparaban sancocho a fuego abierto en el patio de su casa; el humo de la leña le daba muchísimo sabor al plato. La palabra sancocho viene del verbo sancochar, que significa hervir ligeramente. Es una sopa muy sustanciosa, común en toda Latinoamérica, hecha con gallina para guisar, carne de res y menudencias, y se sirve en el almuerzo. ¡No se preocupe, no tiene que encender una fogata para preparar esta versión! Receta en español: Sancocho de carne de res. Para preparar su propio condimento Adobo sin sal, combine 1 cucharada de cada uno de los siguientes: pimienta de limón, ajo en polvo, cebolla en polvo, orégano seco, perejil seco y achiote en polvo, y 1/2 cucharada de comino. Guárdelo en un recipiente hermético hasta por 2 semanas.","6","1 1/3 tazas",
["2 cucharaditas de aceite de oliva","1/2 libra de carne de res magra de la redondilla (cortada en trozos de 1 pulgada)","1 cebolla mediana (picada)","1 pimiento verde mediano (picado)","1 ají cubanela o pimiento Anaheim (picado)","2 tallos de apio (picados)","3 dientes de ajo (picados)","32 onzas de caldo de res sin sal","1/4 de taza de salsa de tomate sin sal añadida","1 cucharada de condimento Adobo","1/2 cucharadita de sal","3 hojas de laurel","3/4 de libra (unas 2 tazas) de yuca fresca o congelada (descongelada y cortada en trozos de 2 pulgadas)","1 plátano verde mediano (pelado y cortado en trozos de 1 pulgada)","1 chayote mediano (pelado y cortado en cubos de 2 pulgadas)","1 tomate grande (picado)","1 taza de cilantro fresco picado"],
["Caliente el aceite en una olla holandesa antiadherente o en una olla grande antiadherente a fuego medio-alto. Agregue la carne y cocine, volteándola de vez en cuando, hasta que se dore, unos 5 minutos. Agregue la cebolla, el pimiento, el ají cubanela, el apio y el ajo. Cocine, revolviendo de vez en cuando, hasta que las verduras estén tiernas, unos 8 minutos.","Agregue el caldo, la salsa de tomate, el condimento adobo, la sal y las hojas de laurel; deje que hierva. Baje el fuego a medio-bajo. Tape y cocine a fuego lento hasta que la carne esté apenas tierna, aproximadamente 1 hora.","Agregue la yuca, el plátano, el chayote y el tomate, y cocine, revolviendo de vez en cuando, hasta que la carne y las verduras estén tiernas al pincharlas con un tenedor, unos 40 minutos.","Retire del fuego. Saque y deseche las hojas de laurel; incorpore el cilantro."],[],[]),
ar=("سانكوتشو اللحم البقري","كان جداي يعدّان السانكوتشو على نار مكشوفة في فناء منزلهما؛ وكان دخان الحطب يضفي على الطبق نكهة رائعة. كلمة سانكوتشو مشتقة من الفعل الإسباني «سانكوتشار» الذي يعني السلق الجزئي. وهو حساء مشبع جدًا شائع في جميع أنحاء أمريكا اللاتينية، يُعد من دجاجة للطهي ولحم البقر والأحشاء ويُقدَّم على الغداء. لا تقلق، لست مضطرًا لإشعال نار لتحضير هذه النسخة! الوصفة بالإسبانية: Sancocho Carne de Res. لتحضير توابل أدوبو الخاصة بك الخالية من الملح، اخلط 1 ملعقة كبيرة من كل من: فلفل الليمون ومسحوق الثوم ومسحوق البصل والأوريغانو المجفف والبقدونس المجفف ومسحوق الأخيوت (الأتشيوتي)، مع ½ ملعقة كبيرة من الكمون. احفظها في وعاء محكم الإغلاق لمدة تصل إلى أسبوعين.","6","1⅓ كوب",
["2 ملعقة صغيرة زيت زيتون","½ رطل لحم بقري قليل الدهن من الفخذ (مقطّع إلى قطع بحجم 1 بوصة)","1 بصلة متوسطة (مفرومة)","1 فلفل رومي أخضر متوسط (مفروم)","1 حبة فلفل كوبانيل أو أنهايم (مفروم)","2 عود كرفس (مفروم)","3 فص ثوم (مفروم)","32 أونصة مرق لحم بقري غير مملح","¼ كوب صلصة طماطم بدون ملح مضاف","1 ملعقة كبيرة توابل أدوبو","½ ملعقة صغيرة ملح","3 ورقة غار","¾ رطل (حوالي 2 كوب) يوكا طازجة أو مجمدة (مذابة ومقطّعة إلى قطع بطول 2 بوصة)","1 حبة موز الجنة (بلانتين) أخضر متوسطة (مقشرة ومقطّعة إلى قطع بحجم 1 بوصة)","1 حبة تشايوت متوسطة (مقشرة ومقطّعة مكعبات بحجم 2 بوصة)","1 حبة طماطم كبيرة (مفرومة)","1 كوب كزبرة خضراء طازجة مفرومة"],
["سخّن الزيت في قدر هولندي غير لاصق أو قدر كبير غير لاصق على نار متوسطة إلى عالية. أضف اللحم واطهه مع تقليبه من حين لآخر حتى يتحمر، حوالي 5 دقائق. أضف البصل والفلفل الرومي والفلفل الكوبانيل والكرفس والثوم. اطهِ مع التقليب من حين لآخر حتى تلين الخضار، حوالي 8 دقائق.","أضف المرق وصلصة الطماطم وتوابل الأدوبو والملح وأوراق الغار؛ واتركه حتى يغلي. اخفض النار إلى متوسطة منخفضة. غطِّه واتركه على نار هادئة حتى يصبح اللحم طريًا بالكاد، حوالي ساعة واحدة.","أضف اليوكا وموز الجنة والتشايوت والطماطم واطهِ مع التقليب من حين لآخر حتى يصبح اللحم والخضار طريين بحيث تخترقهما الشوكة بسهولة، حوالي 40 دقيقة.","ارفعه عن النار. أخرج أوراق الغار وتخلّص منها؛ ثم أضف الكزبرة الخضراء وحرّك."],[],[])))
O.append(R(6435330,
es=("Salmón con miso y bok choy con sésamo en una sola bandeja","Esta cena de inspiración asiática en una sola bandeja incluye bok choy baby asado, un tipo pequeño de repollo chino, y salmón sabroso marinado con miso. Si no encuentra bok choy, las coles de Bruselas o el brócoli funcionarían bien en su lugar. Termine su plato con una guarnición de arroz integral o arroz de coliflor para una comida muy baja en carbohidratos.","4","Un filete de salmón con 1 cabeza de bok choy (2 mitades)",
["2 cucharadas de pasta de miso","1/3 de taza de vinagre de arroz","1 cucharada de aceite de sésamo (dividida)","2 dientes de ajo (picados)","1 cucharada de tamari reducido en sodio","4 filetes de salmón (de 6 onzas cada uno)","4 cabezas de bok choy baby","2 cucharaditas de semillas de sésamo"],
["En un tazón mediano o en una bolsa plástica grande con cierre, mezcle la pasta de miso, el vinagre de arroz, 1/2 cucharada del aceite de sésamo y el ajo. Agregue el salmón y cúbralo con suavidad con la marinada. Tape el tazón o cierre la bolsa y deje marinar en el refrigerador por 15 minutos (si tiene poco tiempo, puede omitir el marinado).","Precaliente el horno a 450° F. Forre una bandeja para hornear con borde con papel pergamino.","Corte los extremos de la raíz del bok choy y corte cada uno por la mitad a lo largo.","Retire los filetes de salmón de la marinada y colóquelos en un extremo de la bandeja preparada, con la piel hacia abajo. (Deseche la marinada sobrante).","En el otro extremo de la bandeja, acomode el bok choy con el lado cortado hacia abajo. Rocíe con la 1/2 cucharada restante de aceite de sésamo y el tamari.","Ase durante 8 minutos, o hasta que el salmón esté bien cocido y el bok choy esté tierno.","Sirva los filetes de salmón y el bok choy en los platos, y espolvoree el bok choy con las semillas de sésamo."],[],[]),
ar=("سلمون بالميسو وبوك تشوي بالسمسم في صينية واحدة","يتميز عشاء الصينية الواحدة هذا المستوحى من المطبخ الآسيوي ببوك تشوي صغير مشوي، وهو نوع صغير من الملفوف الصيني، وسلمون لذيذ متبّل بالميسو. وإذا لم تجد البوك تشوي، فإن كُرنب بروكسل أو البروكلي سيكونان بديلين جيدين. أكمل طبقك بجانب من الأرز البني أو أرز القرنبيط للحصول على وجبة قليلة جدًا الكربوهيدرات.","4","شريحة سلمون واحدة مع رأس بوك تشوي واحد (نصفان)",
["2 ملعقة كبيرة معجون ميسو","⅓ كوب خل الأرز","1 ملعقة كبيرة زيت سمسم (مقسّمة)","2 فص ثوم (مفروم)","1 ملعقة كبيرة تاماري قليل الصوديوم","4 شرائح (6 أونصات لكل منها) سلمون","4 رأس بوك تشوي صغير","2 ملعقة صغيرة بذور سمسم"],
["في وعاء متوسط أو كيس بلاستيكي كبير قابل للإغلاق، اخلط معجون الميسو وخل الأرز و½ ملعقة كبيرة من زيت السمسم والثوم. أضف السلمون وغطِّه برفق بالتتبيلة. غطِّ الوعاء أو أغلق الكيس واتركه ليتبّل في الثلاجة لمدة 15 دقيقة (إذا كان وقتك ضيقًا يمكنك تخطي خطوة التتبيل).","سخّن الفرن مسبقًا إلى 450 درجة فهرنهايت (230 درجة مئوية). بطّن صينية خبز ذات حواف بورق الزبدة.","اقطع أطراف الجذور من البوك تشوي واقطع كل رأس إلى نصفين.","أخرج شرائح السلمون من التتبيلة وضعها على أحد طرفي صينية الخبز المجهّزة، وجهة الجلد إلى الأسفل. (تخلّص من أي تتبيلة متبقية).","على الطرف الآخر من الصينية، رتّب البوك تشوي ووجهه المقطوع إلى الأسفل. رش عليه ½ ملعقة كبيرة المتبقية من زيت السمسم والتاماري.","اشوِه لمدة 8 دقائق أو حتى ينضج السلمون تمامًا ويصبح البوك تشوي طريًا.","قدّم شرائح السلمون والبوك تشوي في الأطباق ورش بذور السمسم على البوك تشوي."],[],[])))
O.append(R(6435485,
es=("Hamburguesa ahumada de res en pan de champiñón","Esta hamburguesa combina carne de res ahumada, queso cheddar derretido y verduras a la parrilla sobre un “pan” sabroso de champiñón portobello, una alternativa baja en carbohidratos al clásico. El calabacín rallado mantiene las hamburguesas jugosas y agrega una dosis discreta de verduras.","4","1 hamburguesa",
["12 onzas de carne molida de res magra (3% de grasa)","1 cucharadita de pimentón ahumado","1 calabacín pequeño (rallado y exprimido para quitar el exceso de humedad)","2 cucharadas de salsa barbacoa (sin azúcar)","4 champiñones portobello grandes","1 cucharada de aceite de oliva extra virgen","4 rebanadas de queso cheddar (sin grasa)","1 cebolla morada mediana (cortada en aros de 1/4 de pulgada de grosor)","1 taza de arúgula baby","1 tomate beefsteak mediano (en rodajas)"],
["En un tazón grande, combine la carne molida, el pimentón ahumado, el calabacín rallado y 1 cucharada de la salsa barbacoa. Mezcle bien con las manos limpias y luego forme cuatro hamburguesas de aproximadamente 3/4 de pulgada de grosor cada una.","Caliente una sartén grill grande a fuego medio-alto. Unte ligeramente las hamburguesas y los champiñones portobello con aceite de oliva. Coloque los champiñones en la parrilla y cocine de 4 a 5 minutos por lado, hasta que estén tiernos y tengan marcas ligeras de la parrilla.","Cocine las hamburguesas por unos 4 minutos del primer lado, hasta que estén ligeramente doradas. Voltee las hamburguesas, cocine 2 minutos más y luego cubra cada una con una rebanada de queso cheddar. Siga cocinando otros 2 minutos, hasta que el queso se derrita y las hamburguesas estén bien cocidas.","Ase los aros de cebolla morada durante unos 2 minutos por lado, hasta que estén ligeramente dorados.","Para servir, coloque cada sombrero de champiñón asado en un plato, con las láminas hacia arriba. Cubra con arúgula, una rodaja de tomate, una hamburguesa con queso derretido y unos aros de cebolla asada. Rocíe con la salsa barbacoa restante."],[],[]),
ar=("برغر اللحم المدخن على خبز الفطر","يجمع هذا البرغر بين اللحم البقري المدخن وجبن الشيدر الذائب والخضار المشوية على «خبز» من فطر البورتوبيلو اللذيذ، كبديل قليل الكربوهيدرات للبرغر الكلاسيكي. ويحافظ الكوسا المبشور على عصارة الأقراص مع إضافة كمية خفية من الخضار.","4","1 برغر",
["12 أونصة لحم بقري مفروم قليل الدهن (3% دهون)","1 ملعقة صغيرة بابريكا مدخنة","1 حبة كوسا صغيرة (مبشورة ومعصورة للتخلص من الرطوبة الزائدة)","2 ملعقة كبيرة صلصة باربكيو (خالية من السكر)","4 حبة فطر بورتوبيلو (كبيرة)","1 ملعقة كبيرة زيت زيتون بكر ممتاز","4 شرائح جبن شيدر (خالٍ من الدسم)","1 بصلة حمراء متوسطة (مقطّعة إلى حلقات بسمك ¼ بوصة)","1 كوب جرجير صغير","1 حبة طماطم بيف ستيك متوسطة (مقطّعة شرائح)"],
["في وعاء كبير، اخلط اللحم المفروم والبابريكا المدخنة والكوسا المبشورة و1 ملعقة كبيرة من صلصة الباربكيو. اخلطها جيدًا بيدين نظيفتين، ثم شكّل الخليط إلى أربعة أقراص بسمك ¾ بوصة تقريبًا لكل منها.","سخّن مقلاة شواء كبيرة على نار متوسطة إلى عالية. افرك الأقراص وفطر البورتوبيلو بزيت الزيتون بشكل خفيف. ضع الفطر على المقلاة واطهه من 4 إلى 5 دقائق لكل جانب حتى يصبح طريًا وتظهر عليه علامات شواء خفيفة.","اطهِ أقراص اللحم لحوالي 4 دقائق على الجانب الأول حتى تتفحم قليلًا. اقلب الأقراص واطهها 2 دقيقة إضافية، ثم ضع على كل منها شريحة من جبن الشيدر. واصل الطهي لمدة 2 دقيقة أخرى حتى يذوب الجبن وتنضج الأقراص تمامًا.","اشوِ حلقات البصل الأحمر حوالي 2 دقيقة لكل جانب حتى تتفحم قليلًا.","للتقديم، ضع كل غطاء فطر مشوي على طبق وجهه ذو الشرائح إلى الأعلى. غطِّه بالجرجير وشريحة طماطم وقرص اللحم مع الجبن الذائب وبعض حلقات البصل المشوية. رش عليه صلصة الباربكيو المتبقية."],[],[])))
O.append(R(6436140,
es=("Camarones criollos con “grits” de coliflor","En esta variación de los grits clásicos, el maíz se sustituye por coliflor y frijoles blancos para obtener una alternativa cremosa que combina perfectamente con el picante de los camarones. Puede sustituir el caldo de pollo por un caldo casero rápido hecho con las cáscaras de los camarones. Considere comprar condimento cajún (por lo general, una mezcla de chile, pimentón ahumado, cayena, ajo, cebolla, sal, pimienta y hierbas) para reducir el tiempo de preparación; además, sirve como un gran condimento para verduras. Si lo compra, se recomienda un condimento cajún sin sal.","4","1 1/2 tazas de grits y 1 taza de camarones criollos",
["2 cucharaditas de aceite vegetal","aproximadamente 2 libras de coliflor (recortada y rallada)","4 dientes de ajo (picados, divididos)","1/2 lata de frijoles blancos bajos en sodio (escurridos y enjuagados)","1 1/2 tazas de caldo de pollo bajo en sodio (dividido)","1/2 taza de agua","1 cucharada de queso parmesano finamente rallado (opcional)","1/2 cucharadita de cebolla en polvo","1/4 de cucharadita de pimienta negra","1 libra de camarones grandes (pelados y desvenados)","1 1/2 cucharaditas de aceite de oliva","2 tallos de apio (en cubos)","1 cebolla amarilla pequeña (en cubos)","1 pimiento verde (en cubos)","2 cucharaditas de condimento criollo sin sal","1 lata (14 onzas) de tomates en cubos","1 hoja de laurel","1 tallo de cebollín (cebolla verde) (en rodajas, para decorar)","1 cucharadita de salsa picante"],
["Para los grits: caliente el aceite vegetal en una olla mediana a fuego medio-alto. Agregue la coliflor y cocine hasta que se ablande y se dore ligeramente, unos 10 minutos. Agregue 1 diente de ajo picado y caliente hasta que desprenda aroma, aproximadamente 1 minuto.","Agregue los frijoles, el caldo y el agua. Cocine por 5 minutos. Apague el fuego. Agregue el parmesano y la cebolla en polvo. Con un machacador o una licuadora, mezcle hasta que quede apenas cremoso y con un poco de textura. Agregue más agua según sea necesario. Sazone con la pimienta. Tape para mantener caliente hasta el momento de servir.","Para los camarones: seque los camarones con una toalla de papel. Caliente 1 1/2 cucharaditas de aceite en una sartén grande a fuego medio-alto y agregue los camarones en una sola capa. Selle ligeramente de un lado hasta que se enrosquen y se doren un poco. Pase los camarones a un plato y agregue el aceite restante a la sartén.","Agregue el apio, la cebolla y el pimiento a la sartén. Baje el fuego a medio y cocine, revolviendo de vez en cuando, hasta que estén tiernos pero sin dorarse demasiado, unos 7 minutos. Si la sartén se seca demasiado mientras se cocinan las verduras, agregue agua según sea necesario.","Agregue los 3 dientes de ajo picados restantes y el condimento, y caliente hasta que desprendan aroma, aproximadamente 1 minuto. Agregue los tomates, el caldo y la hoja de laurel. Con una cuchara, raspe los pedacitos pegados al fondo de la sartén. Deje que hierva y luego baje el fuego para que cueza a fuego lento. Cocine por 10 minutos hasta que espese, revolviendo con frecuencia para evitar que el fondo se queme.","Sirva sobre los “grits” de coliflor y decore con cebollín y salsa picante."],[],[]),
ar=("جمبري كريول مع «غريتس» القرنبيط","في هذه النسخة المختلفة من الغريتس الكلاسيكي، يُستبدل الذرة بالقرنبيط والفاصوليا البيضاء للحصول على بديل كريمي يتناسب تمامًا مع حرارة التوابل في الجمبري. يمكنك استبدال مرق الدجاج بمرق منزلي سريع يُحضَّر من قشور الجمبري. فكّر في شراء توابل كاجون (وهي عادةً خليط من الفلفل الحار والبابريكا المدخنة والفلفل الحار (كايين) والثوم والبصل والملح والفلفل والأعشاب) لتقليل وقت التحضير، وهي أيضًا تتبيلة رائعة للخضار. وفي حال الشراء، يُوصى بتوابل كاجون خالية من الملح.","4","1½ كوب غريتس و1 كوب كريول",
["2 ملعقة صغيرة زيت نباتي","حوالي 2 رطل قرنبيط (مقلّم ومبشور)","4 فص ثوم (مفروم، مقسّم)","½ علبة فاصوليا بيضاء قليلة الصوديوم (مصفاة ومشطوفة)","1½ كوب مرق دجاج قليل الصوديوم (مقسّم)","½ كوب ماء","1 ملعقة كبيرة جبن بارميزان مبشور ناعمًا (اختياري)","½ ملعقة صغيرة مسحوق البصل","¼ ملعقة صغيرة فلفل أسود","1 رطل جمبري كبير (مقشر ومنزوع الأمعاء)","1½ ملعقة صغيرة زيت زيتون","2 عود كرفس (مقطّع مكعبات)","1 بصلة صفراء صغيرة (مقطّعة مكعبات)","1 حبة فلفل رومي أخضر (مقطّعة مكعبات)","2 ملعقة صغيرة توابل كريول خالية من الملح","1 علبة (14 أونصة) طماطم معلبة مقطّعة مكعبات","1 ورقة غار","1 عود بصل أخضر (مقطّع شرائح، للتزيين)","1 ملعقة صغيرة صلصة حارة"],
["للغريتس: سخّن الزيت النباتي في قدر متوسط على نار متوسطة إلى عالية. أضف القرنبيط واطهه حتى يلين ويتحمر قليلًا، حوالي 10 دقائق. أضف فصًّا واحدًا من الثوم المفروم وسخّن حتى تفوح رائحته، حوالي 1 دقيقة.","أضف الفاصوليا والمرق والماء. اطهِ لمدة 5 دقائق. أطفئ النار. أضف البارميزان ومسحوق البصل. باستخدام مهرسة أو خلاط، اخلط حتى يصبح كريميًا فقط مع بقاء بعض القوام. أضف المزيد من الماء حسب الحاجة. تبّل بالفلفل. غطِّه ليبقى دافئًا حتى وقت التقديم.","للجمبري: جفّف الجمبري بمنديل ورقي. سخّن 1½ ملعقة صغيرة من الزيت في مقلاة كبيرة على نار متوسطة إلى عالية وأضف الجمبري في طبقة واحدة. حمّره قليلًا من جانب واحد حتى يلتف ويتفحم قليلًا. انقل الجمبري إلى طبق وأضف بقية الزيت إلى المقلاة.","أضف الكرفس والبصل والفلفل الرومي إلى المقلاة. اخفض النار إلى متوسطة واطهِ مع التقليب من حين لآخر حتى تلين دون أن تتحمر كثيرًا، حوالي 7 دقائق. إذا جفّت المقلاة كثيرًا أثناء طهي الخضار، أضف الماء حسب الحاجة.","أضف فصوص الثوم الثلاثة المفرومة المتبقية والتوابل وسخّن حتى تفوح رائحتها، حوالي 1 دقيقة. أضف الطماطم والمرق وورقة الغار. استخدم ملعقة لكشط أي بقايا ملتصقة بقاع المقلاة. اتركه حتى يغلي ثم اخفض النار ليغلي ببطء. اطهِه لمدة 10 دقائق حتى يتكاثف، مع التقليب المتكرر لمنع احتراق القاع.","قدّمه فوق «غريتس» القرنبيط وزيّنه بالبصل الأخضر والصلصة الحارة."],[],[])))
O.append(R(6436642,
es=("Hummus de lentejas rojas","Este hummus de lentejas rojas es una variación sencilla y saludable de una salsa clásica. En lugar de garbanzos, usa lentejas rojas para obtener una textura suave y un sabor suave a nuez. Se prepara rápidamente con unos pocos ingredientes básicos y es fácil de disfrutar con verduras sin almidón o como untable en sándwiches.","8","2 cucharadas",
["1 1/3 tazas de agua","1/3 de taza de lentejas rojas (secas)","1 cucharada de aceite de oliva","1 cucharada de tahini","1 cucharada de jugo de limón","1/2 cucharadita de ajo (picado)","1/2 cucharadita de comino molido","1/4 de cucharadita de sal","1/4 de cucharadita de pimienta negra"],
["En una cacerola pequeña, combine el agua y las lentejas rojas secas y deje que hierva a fuego medio-alto.","Baje el fuego a bajo y cocine a fuego lento, tapado, revolviendo de vez en cuando, durante unos 30 minutos o hasta que las lentejas se hayan abierto y estén blandas. Deje enfriar y pase a un procesador de alimentos.","Agregue el aceite de oliva, el tahini, el jugo de limón, el ajo picado, el comino, la sal y la pimienta negra, y procese de 30 a 60 segundos o hasta que quede suave, deteniéndose para raspar los lados según sea necesario.","Pase a un recipiente hermético y guarde en el refrigerador por hasta 5 días hasta el momento de servir."],[],[]),
ar=("حمص العدس الأحمر","هذا الحمص بالعدس الأحمر نسخة بسيطة وصحية من الغموس الكلاسيكي. وبدلًا من الحمص الحب، يستخدم العدس الأحمر للحصول على قوام ناعم ونكهة خفيفة تشبه المكسرات. يُحضَّر بسرعة من بضعة مكونات أساسية ويسهل الاستمتاع به مع الخضار غير النشوية أو كدهن للساندويتشات.","8","2 ملعقة كبيرة",
["1⅓ كوب ماء","⅓ كوب عدس أحمر (جاف)","1 ملعقة كبيرة زيت زيتون","1 ملعقة كبيرة طحينة","1 ملعقة كبيرة عصير ليمون","½ ملعقة صغيرة ثوم (مفروم)","½ ملعقة صغيرة كمون مطحون","¼ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود"],
["في قدر صغير، اخلط الماء والعدس الأحمر الجاف واتركه حتى يغلي على نار متوسطة إلى عالية.","اخفض النار إلى منخفضة واتركه يغلي ببطء مع التغطية والتقليب من حين لآخر لمدة 30 دقيقة تقريبًا أو حتى ينفلق العدس ويصبح طريًا. اتركه ليبرد ثم انقله إلى محضّر الطعام.","أضف زيت الزيتون والطحينة وعصير الليمون والثوم المفروم والكمون والملح والفلفل الأسود وشغّل الجهاز لمدة 30 إلى 60 ثانية أو حتى يصبح ناعمًا، مع التوقف لكشط الجوانب عند الحاجة.","انقله إلى وعاء محكم الإغلاق واحفظه في الثلاجة لمدة تصل إلى 5 أيام حتى وقت التقديم."],[],[])))
O.append(R(6437099,
es=("Salmón con dátiles de California y harissa","La dulzura natural de los dátiles de California equilibra el calor ahumado de la harissa en este sabroso plato de salmón, y además aporta fibra, antioxidantes y nutrientes esenciales. La harissa es una pasta de chile del norte de África hecha con pimientos rojos asados y especias. Si no la encuentra en su supermercado, puede sustituirla por chipotles en salsa de adobo para obtener un toque ahumado similar. Las hierbas y las especias son una excelente manera de realzar el sabor de sus platos sin agregar grasa, sodio ni azúcar adicionales. Esta receta muy baja en carbohidratos y baja en carbohidratos también es saludable para el corazón.","4","1 filete de salmón (de 4 onzas)",
["5 dátiles de California (sin hueso)","3 cucharadas de agua","2 cucharadas de aceite de oliva","1 cucharada de harissa o pasta de chile picante","1 cucharada de jugo fresco de lima","3 dientes de ajo (picados finos)","1/2 cucharadita de comino molido","1/2 cucharadita de cilantro molido","1/4 de cucharadita de sal kosher","4 filetes de salmón sockeye (de 4 onzas)","2 cucharadas de cilantro fresco (picado)","1 lima (cortada en 4 gajos)"],
["Precaliente el horno a 400° F.","Pique en trozos grandes 3 dátiles y colóquelos en un tazón pequeño con el agua. Pique los otros 2 dátiles y resérvelos para después.","Caliente el tazón de dátiles en el microondas de 45 segundos a 1 minuto, hasta que se ablanden. Retire el tazón con cuidado y machaque los dátiles con un tenedor hasta formar una pasta espesa. Agregue el aceite de oliva, la pasta de harissa, el jugo de lima, el ajo, el comino, el cilantro molido y la sal, y revuelva hasta combinar.","Coloque los filetes de salmón en una fuente grande para hornear rociada con aceite en aerosol antiadherente. Vierta con una cuchara la salsa de dátiles y harissa sobre el salmón, cubriéndolo por completo. Espolvoree por encima los dátiles picados restantes.","Hornee de 10 a 14 minutos, o hasta que el salmón esté cocido por dentro a 145° F y se desmenuce fácilmente con un tenedor. Retire del horno y cubra el salmón con el cilantro picado.","Sirva cada pieza de salmón con un gajo de lima al lado para exprimir por encima."],[],[]),
ar=("سلمون بتمر كاليفورنيا والهريسة","تعادل الحلاوة الطبيعية لتمر كاليفورنيا حرارة الهريسة المدخنة في طبق السلمون الشهي هذا، مع إضافة الألياف ومضادات الأكسدة والعناصر الغذائية الأساسية. الهريسة معجون فلفل حار من شمال أفريقيا يُصنع من الفلفل الأحمر المشوي والتوابل. وإذا لم تجدها في محل البقالة، يمكنك استبدالها بفلفل الشيبوتلي في صلصة الأدوبو للحصول على نكهة مدخنة مشابهة. الأعشاب والتوابل طريقة ممتازة لتعزيز نكهة أطباقك دون إضافة دهون أو صوديوم أو سكر إضافي. هذه الوصفة القليلة جدًا والقليلة الكربوهيدرات صحية للقلب أيضًا.","4","1 شريحة سلمون (4 أونصات)",
["5 حبات تمر كاليفورنيا (منزوعة النوى)","3 ملعقة كبيرة ماء","2 ملعقة كبيرة زيت زيتون","1 ملعقة كبيرة هريسة أو معجون فلفل حار","1 ملعقة كبيرة عصير ليمون أخضر طازج","3 فص ثوم (مفروم ناعمًا)","½ ملعقة صغيرة كمون مطحون","½ ملعقة صغيرة كزبرة مطحونة","¼ ملعقة صغيرة ملح كوشر","4 شرائح سلمون سوكاي (شريحة 4 أونصات)","2 ملعقة كبيرة كزبرة خضراء طازجة (مفرومة)","1 حبة ليمون أخضر (مقطّعة إلى 4 أرباع)"],
["سخّن الفرن مسبقًا إلى 400 درجة فهرنهايت (200 درجة مئوية).","قطّع 3 حبات تمر تقطيعًا خشنًا وضعها في وعاء صغير مع الماء. قطّع حبتي التمر المتبقيتين وضعهما جانبًا لاستخدامهما لاحقًا.","سخّن وعاء التمر في الميكروويف من 45 ثانية إلى دقيقة حتى يلين. أخرج الوعاء بحذر واهرس التمر بشوكة لتحصل على معجون سميك. أضف زيت الزيتون ومعجون الهريسة وعصير الليمون الأخضر والثوم والكمون والكزبرة المطحونة والملح وقلّب حتى تمتزج.","ضع شرائح السلمون في طبق خبز كبير مدهون ببخاخ غير لاصق. وزّع صلصة التمر والهريسة بالملعقة فوق السلمون لتغطيه بالكامل. رش التمر المقطّع المتبقي في الأعلى.","اخبزه من 10 إلى 14 دقيقة، أو حتى ينضج السلمون من الداخل إلى 145 درجة فهرنهايت (65 درجة مئوية) ويتفتت بسهولة بالشوكة. أخرجه من الفرن وغطِّ السلمون بالكزبرة الخضراء المفرومة.","قدّم كل قطعة سلمون مع ربع ليمونة أخضر على الجانب لعصره فوقها."],[],[])))
O.append(R(6437901,
ar=("سلطة البانزانيلا الإيطالية الكلاسيكية","تتناسب سلطة الخبز والطماطم الكلاسيكية هذه مع أي طبق رئيسي من اللحم أو الدواجن المشوية. ضاعف الوصفة لتصبح أيضًا طبقًا جانبيًا رائعًا في مائدة أعيادك هذا العام!","4","¼ الوصفة",
["2 حبة طماطم متوسطة (مقطّعة مكعبات بحجم 1 بوصة (أو 2 كوب طماطم كرزية، مقطوعة إلى نصفين))","½ ملعقة صغيرة ملح كوشر","5 شرائح خبز إيطالي متعدد الحبوب","1 كوب خيار (مقطّع أرباعًا طوليًا وشرائح رفيعة (حوالي نصف خيارة إنجليزية))","2 عود كرفس (مقطّع بسمك ½ بوصة)","1 بصلة حمراء صغيرة (مقطوعة إلى نصفين وشرائح رفيعة)","¼ ملعقة صغيرة فلفل أسود مطحون طازجًا","2 ملعقة كبيرة خل النبيذ الأحمر","2 ملعقة كبيرة زيت زيتون بكر ممتاز","½ كوب أوراق ريحان طازجة (ممزقة إلى شرائح)","1 كوب أوراق بقدونس إيطالي مسطح (مفرومة خشنًا)"],
["ضع الطماطم في وعاء سلطة كبير ورشها بالملح. اتركها لمدة 5 دقائق.","فتّت الخبز وأضفه إلى الطماطم. أضف بقية مكونات السلطة واخلطها جيدًا."],[],[])))
O.append(R(6438385,
es=("Camarones con especias y limón a la parrilla","Este es un plato rápido, sabroso y bajo en carbohidratos, fácil de preparar. Los camarones se sazonan con especias cálidas y se terminan con un chorrito de limón ahumado a la parrilla para darles más frescura.","5","3 onzas",
["2 cucharadas de perejil fresco","3 limones medianos (partidos por la mitad)","1/4 de cucharadita de pimienta negra","1/4 de cucharadita de sal","1/4 de cucharadita de cilantro molido","2 cucharaditas de chile en polvo","2 cucharaditas de comino molido","1 1/2 cucharadas de aceite de oliva","1 libra de camarones (pelados y desvenados, con la cola)","1 rociada de aceite en aerosol antiadherente, 0.25 g"],
["Rocíe una rejilla de parrilla con aceite en aerosol. Precaliente la parrilla a fuego medio-alto. Si cree que los camarones se caerán por la rejilla, prepare una canasta para pescado para asarlos y rocíe el interior de la canasta con aceite en aerosol."],[],[]),
ar=("جمبري بالتوابل مع الليمون المشوي","هذا طبق سريع ولذيذ وقليل الكربوهيدرات وسهل التحضير. يُتبّل الجمبري بتوابل دافئة ويُنهى بعصرة ليمون مشوي مدخن لمزيد من النضارة.","5","3 أونصات",
["2 ملعقة كبيرة بقدونس طازج","3 حبات ليمون متوسطة (مقطوعة إلى نصفين)","¼ ملعقة صغيرة فلفل أسود","¼ ملعقة صغيرة ملح","¼ ملعقة صغيرة كزبرة مطحونة","2 ملعقة صغيرة مسحوق الفلفل الحار","2 ملعقة صغيرة كمون مطحون","1½ ملعقة كبيرة زيت زيتون","1 رطل جمبري (مقشر ومنزوع الأمعاء، مع الذيول)","1 بخة من بخاخ طهي غير لاصق، 0.25 غرام"],
["ادهن شبكة الشواء ببخاخ الطهي. سخّن الشواية مسبقًا على حرارة متوسطة إلى عالية. إذا كنت تعتقد أن الجمبري سيسقط من شبكة الشواء، فجهّز سلة شواء للأسماك لشوائه فيها وادهن داخل السلة ببخاخ الطهي."],[],[])))
O.append(R(6438939,
es=("Paletas de plátano","Estas paletas de plátano son una forma dulce de refrescarse. Son un postre apto para personas con diabetes y aprobado por los niños, perfecto para el verano.","4","1 paleta",
["2 plátanos (guineos) medianos (maduros)","1/2 taza de yogur griego bajo en grasa (natural)","2 cucharadas de jarabe multiusos sin azúcar"],
["En una licuadora, combine los plátanos, el yogur griego y el jarabe.","Vierta la mezcla en los moldes para paletas y congele por 8 horas o durante toda la noche."],[],[]),
ar=("مثلجات الموز","هذه المثلجات بالموز طريقة حلوة للتبريد. وهي حلوى مناسبة لمرضى السكري ومحبوبة لدى الأطفال، مثالية في الصيف.","4","1 مثلجات",
["2 حبة موز متوسطة (ناضجة)","½ كوب زبادي يوناني قليل الدسم (سادة)","2 ملعقة كبيرة شراب متعدد الاستخدامات خالٍ من السكر"],
["في الخلاط، اخلط الموز والزبادي اليوناني والشراب.","اسكب الخليط في قوالب المثلجات وجمّده لمدة 8 ساعات أو طوال الليل."],[],[])))
O.append(R(6438996,
es=("Salteado de lentejas y verduras","Este salteado de lentejas y verduras es un plato vegetariano nutritivo y satisfactorio que ofrece un buen equilibrio de proteína, fibra y vitaminas gracias a las lentejas y las verduras de colores. Es una receta versátil que le permite sustituir por sus verduras favoritas.","4","1.5 tazas",
["1 taza de lentejas marrones (secas, enjuagadas y escurridas)","2 1/2 tazas de caldo de verduras bajo en sodio","2 cucharadas de salsa de soya baja en sodio","1 cucharada de aceite de sésamo","2 cucharadas de vinagre de arroz","1 cucharada de jarabe de arce","1 cucharadita de aceite vegetal","3 dientes de ajo (picados)","1 cucharada de jengibre fresco (rallado)","3 tazas de brócoli (floretes)","2 zanahorias medianas (en rodajas finas)","1 pimiento rojo mediano (en rodajas finas)","1 pimiento amarillo mediano (en rodajas finas)","1 taza de chícharos (guisantes) dulces (sin las puntas)","1 cucharada de semillas de sésamo","2 tallos de cebollín (picados)"],
["En una cacerola mediana, combine las lentejas y el caldo de verduras. Deje que hierva, luego baje el fuego, tape y cocine a fuego lento de 15 a 20 minutos, o hasta que las lentejas estén tiernas pero conserven su forma. Escurra el exceso de líquido.","En un tazón pequeño, bata la salsa de soya, el aceite de sésamo, el vinagre de arroz y el jarabe de arce. Reserve.","Caliente el aceite vegetal en una sartén grande o wok a fuego medio-alto. Agregue el ajo picado y el jengibre rallado, y saltee durante 30 segundos hasta que desprendan aroma.","Agregue a la sartén el brócoli, las zanahorias, el pimiento rojo, el pimiento amarillo y los chícharos dulces. Saltee de 5 a 7 minutos, hasta que las verduras estén tiernas pero crujientes.","Incorpore las lentejas cocidas a la mezcla de verduras.","Vierta la salsa preparada sobre las lentejas y las verduras. Revuelva bien para asegurarse de que todo quede cubierto con la sabrosa salsa.","Siga cocinando 2 a 3 minutos más, hasta que todo esté caliente.","Decore con las semillas de sésamo y el cebollín picado, si lo desea."],[],[]),
ar=("خضار مقلية مع العدس","هذا الطبق من الخضار المقلية مع العدس وجبة نباتية مفيدة ومشبعة توفر توازنًا جيدًا من البروتين والألياف والفيتامينات من العدس والخضار الملونة. إنها وصفة متعددة الاستخدامات تتيح لك استبدال الخضار بما تفضله.","4","1.5 كوب",
["1 كوب عدس بني (جاف، مشطوف ومصفى)","2½ كوب مرق خضار قليل الصوديوم","2 ملعقة كبيرة صلصة صويا قليلة الصوديوم","1 ملعقة كبيرة زيت سمسم","2 ملعقة كبيرة خل الأرز","1 ملعقة كبيرة شراب القيقب","1 ملعقة صغيرة زيت نباتي","3 فص ثوم (مفروم)","1 ملعقة كبيرة زنجبيل طازج (مبشور)","3 كوب بروكلي (زهيرات)","2 حبة جزر متوسطة (مقطّعة إلى دوائر رفيعة)","1 حبة فلفل رومي أحمر متوسطة (مقطّعة شرائح رفيعة)","1 حبة فلفل رومي أصفر متوسطة (مقطّعة شرائح رفيعة)","1 كوب بازلاء سكر (مقلّمة)","1 ملعقة كبيرة بذور سمسم","2 عود بصل أخضر (مفروم)"],
["في قدر متوسط، اخلط العدس ومرق الخضار. اتركه حتى يغلي ثم اخفض النار وغطِّه واتركه على نار هادئة من 15 إلى 20 دقيقة، أو حتى يصبح العدس طريًا مع احتفاظه بشكله. صفِّ أي سائل زائد.","في وعاء صغير، اخفق صلصة الصويا وزيت السمسم وخل الأرز وشراب القيقب. ضعه جانبًا.","سخّن الزيت النباتي في مقلاة كبيرة أو وعاء ووك على نار متوسطة إلى عالية. أضف الثوم المفروم والزنجبيل المبشور وقلّبهما لمدة 30 ثانية حتى تفوح رائحتهما.","أضف البروكلي والجزر والفلفل الرومي الأحمر والفلفل الرومي الأصفر وبازلاء السكر إلى المقلاة. قلّبها على النار من 5 إلى 7 دقائق حتى تصبح الخضار طرية ومقرمشة.","أضف العدس المطهو إلى خليط الخضار.","اسكب الصلصة المجهّزة فوق العدس والخضار. قلّب جيدًا للتأكد من تغطية كل شيء بالصلصة اللذيذة.","واصل الطهي لمدة 2 إلى 3 دقائق إضافية حتى يسخن كل شيء.","زيّنه ببذور السمسم والبصل الأخضر المفروم إن رغبت."],[],[])))
O.append(R(6440574,
es=("Ensalada de arúgula con nueces y queso de cabra","El sabor picante de la arúgula combina con el queso de cabra cremoso y las nueces de sabor terroso para formar una ensalada satisfactoria y apta para personas con diabetes. Sírvala como entrada o ensalada de acompañamiento cuando quiera algo un poco elegante sin mucho trabajo.","6","1 taza",
["6 tazas de arúgula","1/2 taza de nueces (tostadas y picadas)","1/4 de taza de queso de cabra (desmenuzado)","1 taza de tomates cherry (partidos por la mitad)","1/4 de taza de vinagreta balsámica light"],
["En un tazón grande para ensalada, combine la arúgula, las nueces tostadas y picadas, el queso de cabra desmenuzado y los tomates cherry partidos por la mitad.","En un tazón pequeño, bata el aderezo de vinagreta balsámica, el aceite de oliva extra virgen, la sal y la pimienta.","Rocíe el aderezo sobre la ensalada.","Mezcle la ensalada con suavidad para que quede cubierta de manera uniforme."],[],[]),
ar=("سلطة الجرجير بالجوز وجبن الماعز","تتناسب نكهة الجرجير اللاذعة مع جبن الماعز الكريمي والجوز ذي النكهة الترابية لتكوّن سلطة مشبعة ومناسبة لمرضى السكري. قدّمها كمقبلات أو كسلطة جانبية عندما تريد شيئًا أنيقًا بعض الشيء دون جهد كبير.","6","1 كوب",
["6 كوب جرجير","½ كوب جوز (محمص ومفروم)","¼ كوب جبن ماعز (مفتت)","1 كوب طماطم كرزية (مقطوعة إلى نصفين)","¼ كوب صلصة فينيغريت بلسمية خفيفة"],
["في وعاء سلطة كبير، اخلط الجرجير والجوز المحمص المفروم وجبن الماعز المفتت والطماطم الكرزية المقطوعة إلى نصفين.","في وعاء صغير، اخفق صلصة الفينيغريت البلسمية وزيت الزيتون البكر الممتاز والملح والفلفل.","رش الصلصة فوق السلطة.","قلّب السلطة برفق لتتغطى بالتساوي."],[],[])))
